30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
34	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
35	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
36	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
37	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
