39	
40	    /**
41	     * Builds the owner's self link, formatted {@code '/api/owners/<id>'} where {@code id} is the
42	     * owner's id. Returns {@code null} when the owner has no id.
43	     */
44	    default String selfLink(Owner owner) {
45	        Integer id = owner.getId();
46	        if (id == null) {
47	            return null;
48	        }
49	        return "/api/owners/" + id;
50	    }
51	
52	    /**
53	     * Derives the owner's age band from the birth date, computed as the owner's age on the
54	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
55	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
56	     * date is absent, so an owner created without a birth date carries no age band.
57	     */
58	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum ageBand(Owner owner) {
59	        java.time.LocalDate birthDate = owner.getBirthDate();
60	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
61	        if (birthDate == null || registrationDate == null) {
62	            return null;
63	        }
64	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
65	        if (age < 18) {
66	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
67	        }
68	        if (age < 65) {
69	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
70	        }
71	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
72	    }
73	
74	    /**
75	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
76	     * in the owner's customer code. Returns {@code null} when the customer code is absent.
77	     */
78	    default Integer checkDigit(Owner owner) {
79	        String customerCode = owner.getCustomerCode();
80	        if (customerCode == null) {
81	            return null;
82	        }
83	        int sum = 0;
84	        boolean dbl = true;
85	        for (int i = customerCode.length() - 1; i >= 0; i--) {
86	            char c = customerCode.charAt(i);
87	            if (c < '0' || c > '9') {
88	                continue;
89	            }
90	            int d = c - '0';
91	            if (dbl) {
92	                d *= 2;
93	                if (d > 9) {
94	                    d -= 9;
95	                }
96	            }
97	            sum += d;
98	            dbl = !dbl;
99	        }
100	        return (10 - (sum % 10)) % 10;
101	    }
102	
103	    /**
104	     * Derives the owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64 hex
105	     * characters) of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}. The telephone and
106	     * email segments are empty when the respective field is absent, and the last-name segment is the
107	     * {@link #soundex(String) Soundex code} of the owner's last name. The telephone and email are already
108	     * stored in their normalized (E.164 / lower-cased) form, so the stored values are used directly. This
109	     * is the single key against which owner duplicates are detected: two owners collide only when their
110	     * whole keys match.
111	     */
112	    default String identityKey(Owner owner) {
113	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
114	        String email = owner.getEmail() == null ? "" : owner.getEmail();
115	        String lastNameCode = OwnerIdentity.soundex(owner.getLastName());
116	        return OwnerIdentity.sha256Hex(telephone + "|" + email + "|" + lastNameCode);
117	    }
118	
119	    /**
120	     * Fixed city-to-region table used to derive an owner's locality.
121	     */
122	    java.util.Map<String, String> CITY_REGION =
123	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
124	
125	    /**
126	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
127	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
128	     */
129	    java.util.Map<String, int[]> REGION_POSTCODES =
130	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
131	
132	    /**
133	     * Derives the owner's locality, the {@code REGION} segment of the owner's customer code (the
134	     * region-and-hash identity {@code '<REGION>-<HASH8>'}). Only when no customer code is present does
135	     * it fall back to deriving the region directly, preferring the postcode's {@link #REGION_POSTCODES}
136	     * range and then the fixed {@link #CITY_REGION} city table. Returns the canonical region string, or
137	     * {@code "UNKNOWN"} when neither source resolves a region.
138	     */
139	    default String locality(Owner owner) {
140	        String customerCode = owner.getCustomerCode();
141	        if (customerCode != null) {
142	            int dash = customerCode.indexOf('-');
143	            String region = dash >= 0 ? customerCode.substring(0, dash) : customerCode;
144	            if (!region.isEmpty()) {
145	                return region;
146	            }
147	        }
148	        String postcode = owner.getPostcode();
149	        if (postcode != null) {
150	            try {
151	                int value = Integer.parseInt(postcode.trim());
152	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
153	                    int[] range = entry.getValue();
154	                    if (value >= range[0] && value <= range[1]) {
155	                        return entry.getKey();
156	                    }
157	                }
158	            }
159	            catch (NumberFormatException ex) {
160	                // Not a numeric postcode; fall back to the city table below.
161	            }
162	        }
163	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
164	    }
165	
166	    /**
167	     * Fixed region-to-timezone table used to derive an owner's timezone as an IANA name.
168	     */
169	    java.util.Map<String, String> REGION_TIMEZONE =
170	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
171	
172	    /**
173	     * Derives the owner's timezone as an IANA name from the owner's {@link #locality(Owner) locality}
174	     * (region) via the fixed {@link #REGION_TIMEZONE} table: {@code NSW -> Australia/Sydney},
175	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}. Returns {@code null} when
176	     * the region does not resolve to a known timezone (e.g. the locality is {@code "UNKNOWN"}).
177	     */
178	    default String timezone(Owner owner) {
179	        return REGION_TIMEZONE.get(locality(owner));
180	    }
181	
182	    /**
183	     * Known E.164 country calling codes, longest first, used to split a stored E.164 telephone into
184	     * its country code and national digits when formatting {@link #telephoneDisplay(Owner)}.
185	     */
186	    String[] TELEPHONE_COUNTRY_CODES = {"61", "1"};
187	
188	    /**
189	     * Formats the owner's stored E.164 telephone for humans: the country code, a space, then the
190	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
191	     * The country code is recognised from the {@link #TELEPHONE_COUNTRY_CODES} table; when none matches,
192	     * all digits after the {@code '+'} are treated as the national number. Returns {@code null} when the
193	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164 number.
194	     */
195	    default String telephoneDisplay(Owner owner) {
196	        String telephone = owner.getTelephone();
197	        if (telephone == null) {
198	            return null;
199	        }
200	        if (!telephone.startsWith("+")) {
201	            return telephone;
202	        }
203	        String digits = telephone.substring(1);
204	        if (!digits.chars().allMatch(Character::isDigit)) {
205	            return telephone;
206	        }
207	        String countryCode = "";
208	        for (String code : TELEPHONE_COUNTRY_CODES) {
209	            if (digits.startsWith(code) && digits.length() > code.length()) {
210	                countryCode = code;
211	                break;
212	            }
213	        }
214	        String national = digits.substring(countryCode.length());
215	        StringBuilder grouped = new StringBuilder();
216	        for (int i = 0; i < national.length(); i++) {
217	            if (i > 0 && i % 3 == 0) {
218	                grouped.append(' ');
219	            }
220	            grouped.append(national.charAt(i));
221	        }
222	        return "+" + countryCode + " " + grouped;
223	    }
224	
225	    /**
226	     * Derives the owner's preferred contact channel: {@code "EMAIL"} when an email address is
227	     * present (non-blank), otherwise {@code "PHONE"}.
228	     */
229	    default String contactPreference(Owner owner) {
230	        String email = owner.getEmail();
231	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
232	    }
233	
234	    /**
235	     * Computes the owner's membership points. Starts at {@code 0} and adds {@code 2} when an email
236	     * is present, {@code 1} when the owner has no namesakes ({@code namesakeCount} is {@code 0}),
237	     * {@code 2} for a household of {@code 3} or more ({@code householdSize}), and {@code 3} when the
238	     * owner's tenure spans at least one elapsed fiscal year (the {@code registrationDate}'s fiscal
239	     * year is earlier than the current date's fiscal year).
240	     */
241	    default Integer membershipPoints(Owner owner) {
242	        Integer namesakeCount = owner.getNamesakeCount();
243	        String email = owner.getEmail();
244	        Integer householdSize = owner.getHouseholdSize();
245	        int points = 0;
246	        if (email != null && !email.isBlank()) {
247	            points += 2;
248	        }
249	        if (namesakeCount != null && namesakeCount == 0) {
250	            points += 1;
251	        }
252	        if (householdSize != null && householdSize >= 3) {
253	            points += 2;
254	        }
255	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
256	        boolean hasTenure = registrationDate != null
257	            && fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate) >= 1;
258	        if (hasTenure) {
259	            points += 3;
260	        }
261	        return points;
262	    }
263	
264	    /**
265	     * Derives the owner's membership level, a number from 1 to 4, from the owner's
266	     * {@link #membershipPoints(Owner) membership points}: level {@code 1} for {@code 0-1} points,
267	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
268	     *
269	     * <p>The derived level is then capped by the owner's {@code membershipLevelCap} when one was
270	     * snapshotted at creation: a new owner's membership level cannot exceed one above the highest
271	     * membership level among their existing household members. When no cap is present (the owner had no
272	     * existing household member) the derived level is returned unchanged.
273	     */
274	    default Integer membershipLevel(Owner owner) {
275	        int points = membershipPoints(owner);
276	        int level;
277	        if (points <= 1) {
278	            level = 1;
279	        } else if (points <= 3) {
280	            level = 2;
281	        } else if (points <= 5) {
282	            level = 3;
283	        } else {
284	            level = 4;
285	        }
286	        Integer cap = owner.getMembershipLevelCap();
287	        if (cap != null && level > cap) {
288	            return cap;
289	        }
290	        return level;
291	    }
292	
293	    /**
294	     * Known regions considered {@code METRO} for the owner's segment: NSW, VIC and QLD.
295	     */
296	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
297	
298	    /**
299	     * Derives the owner's segment, formatted {@code '<TIER>_<AREA>'}. {@code TIER} is {@code PREMIUM}
300	     * when the owner's {@link #membershipLevel(Owner) membership level} is {@code 3} or more, otherwise
301	     * {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's {@link #locality(Owner) locality}
302	     * is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
303	     */
304	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
305	        Integer level = membershipLevel(owner);
306	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
307	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
308	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.OwnerSegmentEnum
309	            .fromValue(tier + "_" + area);
310	    }
311	
312	    /**
313	     * Builds the owner's membership number, formatted {@code '<customerCode>-M<YY>'} where
314	     * {@code YY} is the last two digits of the registration date's fiscal year (e.g.
315	     * {@code "NSW-3F2A1B9C-M26"}). Returns {@code null} when the customer code or registration date
316	     * is absent.
317	     */
318	    default String membershipNumber(Owner owner) {
319	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
320	            return null;
321	        }
322	        int yy = fiscalYearValue(owner.getRegistrationDate()) % 100;
323	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
324	    }
325	
326	    /**
327	     * Derives the owner's fiscal year from the business-day-adjusted registration date, formatted
328	     * {@code 'FY<YY>'} where {@code YY} is the last two digits of the fiscal year (e.g.
329	     * {@code "FY26"}). Returns {@code null} when the registration date is absent.
330	     */
331	    default String fiscalYear(Owner owner) {
332	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
333	        if (registrationDate == null) {
334	            return null;
335	        }
336	        return String.format("FY%02d", fiscalYearValue(registrationDate) % 100);
337	    }
338	
339	    /**
340	     * Computes the fiscal year, as a full four-digit year, of the given date. The fiscal year starts
341	     * on 1 July and is named by the calendar year in which it ends, so a date on or after 1 July
342	     * belongs to the following calendar year's fiscal year.
343	     */
344	    default int fiscalYearValue(java.time.LocalDate date) {
345	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
346	    }
347	
348	    /**
349	     * Builds the owner's salutation: the supplied title and last name joined by a single space
350	     * (e.g. {@code "DR Franklin"}) when a title is present (non-blank), otherwise just the last
351	     * name. Returns {@code null} when the owner has no last name.
352	     */
353	    default String salutation(Owner owner) {
354	        String lastName = owner.getLastName();
355	        String title = owner.getTitle();
356	        if (title == null || title.isBlank()) {
357	            return lastName;
358	        }
359	        return title + " " + lastName;
360	    }
361	
362	    /**
363	     * Builds the owner's initials as the upper-cased first letters of the first and last
364	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
365	     */
366	    default String initials(Owner owner) {
367	        String first = owner.getFirstName();
368	        String last = owner.getLastName();
369	        StringBuilder sb = new StringBuilder();
370	        if (first != null && !first.isEmpty()) {
371	            sb.append(Character.toUpperCase(first.charAt(0))).append('.');
372	        }
373	        if (last != null && !last.isEmpty()) {
374	            sb.append(Character.toUpperCase(last.charAt(0))).append('.');
375	        }
376	        return sb.toString();
377	    }
378	
379	    Owner toOwner(OwnerDto ownerDto);
380	
381	    @Mapping(target = "id", ignore = true)
382	    @Mapping(target = "pets", ignore = true)
383	    Owner toOwner(OwnerFieldsDto ownerDto);
384	
385	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
386	
387	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
388	
389	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
390	        OwnerPageDto ownerPageDto = new OwnerPageDto();
391	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
392	        ownerPageDto.setPage(ownerPage.getNumber());
393	        ownerPageDto.setSize(ownerPage.getSize());
394	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
395	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
396	        return ownerPageDto;
397	    }
398	}
