192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
197	        String idempotencyKey = idempotencyKey();
198	        if (idempotencyKey != null) {
199	            Integer existingId = idempotentOwnerIds.get(idempotencyKey);
200	            if (existingId != null) {
201	                Owner existing = this.clinicService.findOwnerById(existingId);
202	                if (existing != null) {
203	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
204	                }
205	            }
206	        }
207	        validateRequiredOwnerFields(ownerFieldsDto);
208	        HttpHeaders headers = new HttpHeaders();
209	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
210	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
211	        owner.setTelephone(normalizedTelephone);
212	        owner.setEmail(normalizeEmail(owner.getEmail()));
213	        applyAddress(owner);
214	        validatePostcode(owner.getPostcode(), owner.getCity());
215	        rejectFutureRegistrationDate(owner.getRegistrationDate());
216	        LocalDate effectiveRegistrationDate =
217	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
218	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
219	        rejectDailyLimitReached(owner.getRegistrationDate());
220	        rejectCityAtCapacity(owner.getCity());
221	        owner.setCapacityWarning(isApproachingCityCapacity(owner.getCity()));
222	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
223	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
224	        rejectDuplicateIdentity(owner, sharesHousehold);
225	        assignPossibleDuplicate(owner, sharesHousehold);
226	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
227	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
228	        owner.setHouseholdSize(countHousehold(owner.getHouseholdId()));
229	        owner.setMembershipLevelCap(membershipLevelCap(owner.getHouseholdId()));
230	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
231	        this.clinicService.saveOwner(owner);
232	        if (idempotencyKey != null) {
233	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
234	        }
235	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
236	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
237	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
238	        emitOwnerCreatedEvent(owner);
239	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
240	        headers.setLocation(UriComponentsBuilder.newInstance()
241	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
242	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
243	    }
244	
245	    /**
246	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, returning
247	     * {@code null} when the header is absent or blank so callers can treat those uniformly as "no key".
248	     *
249	     * @return the trimmed idempotency key, or {@code null} when none was supplied
250	     */
251	    private String idempotencyKey() {
252	        String value = request.getHeader(IDEMPOTENCY_KEY_HEADER);
253	        if (value == null || value.isBlank()) {
254	            return null;
255	        }
256	        return value.strip();
257	    }
258	
259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
262	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
263	        if (currentOwner == null) {
264	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	        }
266	        currentOwner.setAddress(ownerFieldsDto.getAddress());
267	        currentOwner.setCity(ownerFieldsDto.getCity());
268	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
269	        currentOwner.setLastName(ownerFieldsDto.getLastName());
270	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
271	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
272	        this.clinicService.saveOwner(currentOwner);
273	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Transactional
278	    @Override
279	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
280	        Owner owner = this.clinicService.findOwnerById(ownerId);
281	        if (owner == null) {
282	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	        }
284	        owner.setDeleted(Boolean.TRUE);
285	        this.clinicService.saveOwner(owner);
286	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
287	    }
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
