373	    /**
374	     * Emits the immutable, structured {@code OWNER_CREATED} audit event for a freshly persisted owner.
375	     * The event is a JSON object {@code {seq, ownerId, customerCode, membershipLevel, event}} published
376	     * to the {@code AUDIT} logger alongside the human-readable audit line. {@code seq} is a strictly
377	     * increasing sequence across all creates (see {@link #OWNER_EVENT_SEQ}), giving the event stream a
378	     * total order.
379	     *
380	     * <p>The identifier field carries the owner's <em>current primary identifier</em>, obtained from
381	     * {@link #primaryIdentifier(Owner)}. Today that is the customer code; when a later checkpoint unifies
382	     * the customer code into the member id, {@code primaryIdentifier} switches to the member id and the
383	     * event carries the member id instead — without any change here.
384	     *
385	     * @param owner the owner that was just created and persisted
386	     */
387	    private void emitOwnerCreatedEvent(Owner owner) {
388	        OwnerCreatedEvent event = new OwnerCreatedEvent(
389	            OWNER_EVENT_SEQ.incrementAndGet(),
390	            owner.getId(),
391	            primaryIdentifier(owner),
392	            ownerMapper.membershipLevel(owner));
393	        AUDIT.info(event.toJson());
394	    }
