396	    /**
397	     * Returns the owner's current primary identifier, the single value the {@code OWNER_CREATED} audit
398	     * event carries to identify the owner. This is currently the {@link Owner#getCustomerCode() customer
399	     * code}; it is intentionally the only place that decides which field is "primary", so that when the
400	     * customer code is later unified into the member id, only this method changes and the event
401	     * automatically carries the member id.
402	     *
403	     * @param owner the owner being created
404	     * @return the owner's current primary identifier
405	     */
406	    private String primaryIdentifier(Owner owner) {
407	        return owner.getCustomerCode();
408	    }
