410	    /**
411	     * Immutable, structured {@code OWNER_CREATED} audit event. Serialized to a compact JSON object
412	     * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}} for the {@code AUDIT}
413	     * log. Being a record, once constructed its fields cannot change, so the emitted event is a faithful
414	     * snapshot of the owner at creation time.
415	     *
416	     * @param seq strictly increasing sequence number across all creates
417	     * @param ownerId the created owner's id
418	     * @param customerCode the owner's current primary identifier at creation time
419	     * @param membershipLevel the owner's effective membership level at creation time
420	     */
421	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, Integer membershipLevel) {
422	
423	        private String toJson() {
424	            return "{\"seq\":" + seq
425	                + ",\"ownerId\":" + ownerId
426	                + ",\"customerCode\":" + jsonValue(customerCode)
427	                + ",\"membershipLevel\":" + membershipLevel
428	                + ",\"event\":\"OWNER_CREATED\"}";
429	        }
430	
431	        /** Renders a nullable string as a JSON string literal (with escaping) or {@code null}. */
432	        private static String jsonValue(String value) {
433	            if (value == null) {
434	                return "null";
435	            }
436	            StringBuilder sb = new StringBuilder(value.length() + 2);
437	            sb.append('"');
438	            for (int i = 0; i < value.length(); i++) {
439	                char c = value.charAt(i);
440	                switch (c) {
441	                    case '"' -> sb.append("\\\"");
442	                    case '\\' -> sb.append("\\\\");
443	                    case '\n' -> sb.append("\\n");
444	                    case '\r' -> sb.append("\\r");
445	                    case '\t' -> sb.append("\\t");
446	                    default -> sb.append(c);
447	                }
448	            }
449	            sb.append('"');
450	            return sb.toString();
451	        }
452	    }
