454	    /**
455	     * Builds the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'} where
456	     * {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion})
457	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
458	     * normalized telephone concatenated with the last name. For example an owner in the NSW postcode
459	     * range gets a code such as {@code 'NSW-3F2A1B9C'}.
460	     *
461	     * <p>When the computed code collides with an existing owner's customer code, it is de-duplicated
462	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result
463	     * unique across all existing owners' customer codes. The de-duplicated code is what gets assigned.
464	     *
465	     * @param owner the owner being created, whose postcode, city and last name feed the code
466	     * @param normalizedTelephone the owner's E.164-normalized telephone
467	     * @return the assigned customer code, de-duplicated against existing owners if necessary
468	     */
469	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
470	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
471	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
472	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
473	        String baseCode = region + "-" + hash8;
474	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
475	            .map(Owner::getCustomerCode)
476	            .filter(code -> code != null)
477	            .collect(java.util.stream.Collectors.toSet());
478	        if (!existingCodes.contains(baseCode)) {
479	            return baseCode;
480	        }
481	        int n = 2;
482	        while (existingCodes.contains(baseCode + "-" + n)) {
483	            n++;
484	        }
485	        return baseCode + "-" + n;
486	    }
