488	    /**
489	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
490	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
491	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
492	     *
493	     * @param postcode the owner's postcode, may be {@code null}
494	     * @param city the owner's city, used to resolve the region when the postcode does not
495	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
496	     */
497	    private String deriveRegion(String postcode, String city) {
498	        if (postcode != null) {
499	            try {
500	                int value = Integer.parseInt(postcode.trim());
501	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
502	                    int[] range = entry.getValue();
503	                    if (value >= range[0] && value <= range[1]) {
504	                        return entry.getKey();
505	                    }
506	                }
507	            } catch (NumberFormatException ex) {
508	                // Not a numeric postcode; fall back to the city table below.
509	            }
510	        }
511	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
512	    }
513	
514	    /**
515	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
516	     * given input's UTF-8 bytes.
517	     *
518	     * @param input the string to hash
519	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
520	     */
521	    private String sha256Hex8(String input) {
522	        try {
523	            byte[] digest = MessageDigest.getInstance("SHA-256")
524	                .digest(input.getBytes(StandardCharsets.UTF_8));
525	            StringBuilder hex = new StringBuilder();
526	            for (int i = 0; i < 4; i++) {
527	                hex.append(String.format("%02X", digest[i]));
528	            }
529	            return hex.toString();
530	        } catch (NoSuchAlgorithmException ex) {
531	            throw new IllegalStateException("SHA-256 not available", ex);
532	        }
533	    }
