535	    /**
536	     * Rejects an owner payload that is missing or blank in any of the required fields
537	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
538	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
539	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
540	     * guard enforces the rule uniformly for every required field.
541	     *
542	     * @param ownerFieldsDto the submitted owner payload
543	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
544	     */
545	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
546	        List<String> invalidFields = new ArrayList<>();
547	        if (isBlank(ownerFieldsDto.getFirstName())) {
548	            invalidFields.add("firstName");
549	        }
550	        if (isBlank(ownerFieldsDto.getLastName())) {
551	            invalidFields.add("lastName");
552	        }
553	        if (isBlank(ownerFieldsDto.getAddressLine1())
554	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
555	            invalidFields.add("address");
556	        }
557	        if (isBlank(ownerFieldsDto.getCity())) {
558	            invalidFields.add("city");
559	        }
560	        if (isBlank(ownerFieldsDto.getTelephone())) {
561	            invalidFields.add("telephone");
562	        }
563	        if (!invalidFields.isEmpty()) {
564	            throw new InvalidOwnerFieldsException(invalidFields);
565	        }
566	    }
