585	    /**
586	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
587	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
588	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
589	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
590	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
591	     * and returned exactly as given.
592	     *
593	     * @param postcode the submitted postcode, may be {@code null} when absent
594	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
595	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
596	     */
597	    private void validatePostcode(String postcode, String city) {
598	        if (postcode == null) {
599	            return;
600	        }
601	        if (!postcode.matches("[0-9]{4}")) {
602	            throw new InvalidOwnerFieldsException(List.of("postcode"));
603	        }
604	        String region = city == null ? null : CITY_REGION.get(city);
605	        if (region == null) {
606	            return;
607	        }
608	        int[] range = REGION_POSTCODES.get(region);
609	        int value = Integer.parseInt(postcode);
610	        if (value < range[0] || value > range[1]) {
611	            throw new InvalidOwnerFieldsException(List.of("postcode"));
612	        }
613	    }
614	
615	    /**
616	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
617	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
618	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
619	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
620	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
621	     *
622	     * @param telephone the raw telephone value from the submitted owner payload
623	     * @return the normalized E.164 telephone number
624	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
625	     */
626	    private String normalizeTelephone(String telephone) {
627	        String raw = telephone == null ? "" : telephone.strip();
628	        boolean hasCountryCode = raw.startsWith("+");
629	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
630	        String digits;
631	        if (hasCountryCode) {
632	            digits = cleaned.substring(1);
633	        } else {
634	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
635	            digits = "61" + national;
636	        }
637	        if (!digits.matches("[0-9]{8,15}")) {
638	            throw new InvalidOwnerFieldsException(List.of("telephone"));
639	        }
640	        validateNationalNumberLength(digits);
641	        return "+" + digits;
642	    }
643	
644	    /**
645	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
646	     * country calling code) has the exact length required for that country. The country code is matched
647	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
648	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
649	     *
650	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
651	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
652	     */
653	    private void validateNationalNumberLength(String digits) {
654	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
655	            String countryCode = entry.getKey();
656	            if (digits.startsWith(countryCode)) {
657	                int nationalLength = digits.length() - countryCode.length();
658	                if (nationalLength != entry.getValue()) {
659	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
660	                }
661	                return;
662	            }
663	        }
664	    }
665	
666	    /**
667	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
668	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
669	     * accepted value is trimmed and lower-cased before it is stored and returned.
670	     *
671	     * @param email the raw email value from the submitted owner payload, may be {@code null}
672	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
673	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
674	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
675	     */
676	    private String normalizeEmail(String email) {
677	        if (email == null) {
678	            return null;
679	        }
680	        String trimmed = email.strip();
681	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
682	            throw new InvalidOwnerFieldsException(List.of("email"));
683	        }
684	        String normalized = trimmed.toLowerCase(Locale.ROOT);
685	        String domain = normalized.substring(normalized.indexOf('@') + 1);
686	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
687	            throw new InvalidOwnerFieldsException(List.of("email"));
688	        }
689	        return normalized;
690	    }
