692	    /**
693	     * Rejects creating an owner whose derived identity key (the SHA-256 hex digest of
694	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}, see {@link OwnerMapper#identityKey})
695	     * exactly equals that of an existing non-deleted owner. Two owners are treated as duplicates only when
696	     * their whole identity keys match, so owners who share a last-name Soundex but differ in telephone or
697	     * email are not duplicates and are admitted (flagged as a soft match instead). Such an owner is rejected
698	     * with a 409, <em>unless</em> the request opts into {@code sharesHousehold}, which bypasses the block
699	     * entirely.
700	     *
701	     * @param owner the owner being created, whose identity key is matched
702	     * @param sharesHousehold whether the request declared the owner a shared-household member
703	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key
704	     */
705	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
706	        if (sharesHousehold) {
707	            return;
708	        }
709	        String identityKey = ownerMapper.identityKey(owner);
710	        boolean duplicate = this.clinicService.findAllOwners().stream()
711	            .filter(existing -> !isDeleted(existing))
712	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
713	        if (duplicate) {
714	            throw new DuplicateOwnerIdentityException(identityKey);
715	        }
716	    }
