718	    /**
719	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
720	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
721	     * owner whose {@link OwnerMapper#identityKey identity key} <em>differs</em> from an existing owner's
722	     * but which shares that owner's last-name {@link OwnerMapper#soundex Soundex code} and postcode. When
723	     * such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
724	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
725	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
726	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
727	     *
728	     * <p>Because the telephone is part of the identity key, two owners with the same last name and postcode
729	     * but different telephones no longer collide on the identity key, so they are admitted as a soft match
730	     * here rather than rejected as a hard household duplicate.
731	     *
732	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the duplicate
733	     * block) is never a <em>suspected</em> duplicate: it is knowingly created as another member of the
734	     * household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
735	     * {@code null} without consulting the existing population.
736	     *
737	     * @param owner the owner being created, whose last-name Soundex and postcode are matched
738	     * @param sharesHousehold whether the request declared the owner a shared-household member
739	     */
740	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
741	        if (sharesHousehold) {
742	            owner.setPossibleDuplicateOf(null);
743	            owner.setPossibleDuplicate(false);
744	            return;
745	        }
746	        String postcode = owner.getPostcode();
747	        Integer matchId = null;
748	        if (postcode != null) {
749	            String identityKey = ownerMapper.identityKey(owner);
750	            String lastNameCode = OwnerIdentity.soundex(owner.getLastName());
751	            for (Owner existing : this.clinicService.findAllOwners()) {
752	                if (!isDeleted(existing)
753	                    && postcode.equals(existing.getPostcode())
754	                    && lastNameCode.equals(OwnerIdentity.soundex(existing.getLastName()))
755	                    && !identityKey.equals(ownerMapper.identityKey(existing))
756	                    && existing.getId() != null
757	                    && (matchId == null || existing.getId() < matchId)) {
758	                    matchId = existing.getId();
759	                }
760	            }
761	        }
762	        owner.setPossibleDuplicateOf(matchId);
763	        owner.setPossibleDuplicate(matchId != null);
764	    }
