807	     * Rolls an effective registration date forward onto a business day. A registration date must fall
808	     * on a weekday that is not a public holiday: when the supplied or defaulted date is a Saturday, a
809	     * Sunday, or a listed public holiday it is rolled forward one day at a time until it reaches the
810	     * next non-holiday business day, and that adjusted date becomes the owner's {@code registrationDate}.
811	     * A date that is already a non-holiday weekday is returned unchanged. Every value derived from the
812	     * registration date (the daily create-limit count, the membership number's year segment, and so on)
813	     * uses this adjusted date.
814	     *
815	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
816	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
817	     */
818	    /**
819	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
820	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
821	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
822	     * against the date exactly as supplied, before it is rolled forward onto a business day.
823	     *
824	     * @param registrationDate the registration date supplied in the request, may be {@code null}
825	     * @throws FutureRegistrationDateException if the supplied date is after the server date
826	     */
827	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
828	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
829	            throw new FutureRegistrationDateException(registrationDate);
830	        }
831	    }
832	
833	    private LocalDate rollToBusinessDay(LocalDate date) {
834	        LocalDate adjusted = date;
835	        while (!isBusinessDay(adjusted)) {
836	            adjusted = adjusted.plusDays(1);
837	        }
838	        return adjusted;
839	    }
840	
841	    private boolean isBusinessDay(LocalDate date) {
842	        DayOfWeek day = date.getDayOfWeek();
843	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
844	            return false;
845	        }
846	        return !PUBLIC_HOLIDAYS.contains(date);
847	    }
848	
849	    private void rejectDailyLimitReached(LocalDate registrationDate) {
850	        long ownersToday = this.clinicService.findAllOwners().stream()
851	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
852	            .count();
853	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
854	            throw new DailyOwnerLimitExceededException(registrationDate);
855	        }
856	    }
857	
858	    /**
859	     * The number of owners that must already share a {@code registrationDate} before a newly created
860	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
861	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
862	     */
863	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
864	
865	    /**
866	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
867	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
868	     * the same registration date at the time this owner is created. Existing owners are counted by their
869	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
870	     * daily create-limit accumulation.
871	     *
872	     * @param registrationDate the registration date of the owner being created
873	     * @return {@code true} if the day already holds more than the threshold number of owners
874	     */
875	    private boolean isBulkSignupDay(LocalDate registrationDate) {
876	        long ownersToday = this.clinicService.findAllOwners().stream()
877	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
878	            .count();
879	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
880	    }
881	
882	    private void rejectCityAtCapacity(String city) {
883	        String normalizedCity = normalizeForComparison(city);
884	        long ownersInCity = this.clinicService.findAllOwners().stream()
885	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
886	            .count();
887	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
888	            throw new OwnerCityCapacityExceededException(city);
889	        }
890	    }
891	
892	    /**
893	     * The number of owners a city must already hold before a newly created owner in that city is
894	     * flagged as approaching capacity. Once a city already contains at least this many owners (but
895	     * still fewer than {@link #MAX_OWNERS_PER_CITY}), the new owner's {@code capacityWarning} is set.
896	     */
897	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
898	
899	    /**
900	     * Determines whether the owner being created is approaching the per-city capacity limit. The
901	     * warning is raised when the owner's city already contains between {@link
902	     * #CITY_CAPACITY_WARNING_THRESHOLD} and {@code MAX_OWNERS_PER_CITY - 1} owners (inclusive) at the
903	     * time this owner is created; the hard rejection at {@link #MAX_OWNERS_PER_CITY} is unchanged.
904	     * Existing owners' cities are compared case-insensitively with surrounding and repeated internal
905	     * whitespace collapsed (see {@link #normalizeForComparison}), matching {@link #rejectCityAtCapacity}.
906	     *
907	     * @param city the city of the owner being created
908	     * @return {@code true} if the city already holds 40-49 owners
909	     */
910	    private boolean isApproachingCityCapacity(String city) {
911	        String normalizedCity = normalizeForComparison(city);
912	        long ownersInCity = this.clinicService.findAllOwners().stream()
913	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
914	            .count();
915	        return ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD && ownersInCity < MAX_OWNERS_PER_CITY;
916	    }
917	
918	    /**
919	     * Counts how many owners belong to the household the owner being created has just been assigned to,
920	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
921	     * given identifier; the owner being created is added on because it is counted before being persisted.
922	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
923	     * household of one. The value is snapshotted on the owner.
924	     *
925	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
926	     * @return the number of household members, including the owner being created
927	     */
928	    private int countHousehold(String householdId) {
929	        if (householdId == null) {
930	            return 1;
931	        }
932	        long existing = this.clinicService.findAllOwners().stream()
933	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
934	            .count();
935	        return (int) existing + 1;
936	    }
937	
938	    /**
939	     * Computes the membership-level ceiling for the owner being created, snapshotted at creation time.
940	     * A new owner's membership level cannot exceed one above the current maximum membership level among
941	     * their existing household members: the returned cap is that maximum plus one. Existing household
942	     * members are the non-deleted owners already carrying the same {@code householdId}, and their
943	     * membership level is their effective (already-capped) {@link OwnerMapper#membershipLevel level}.
944	     * Returns {@code null} when there is no existing household member, in which case no cap applies.
945	     *
946	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
947	     * @return one above the highest household member's membership level, or {@code null} when none exist
948	     */
949	    private Integer membershipLevelCap(String householdId) {
950	        if (householdId == null) {
951	            return null;
952	        }
953	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
954	            .filter(existing -> !isDeleted(existing))
955	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
956	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
957	            .max();
958	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
959	    }
960	
961	    /**
962	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
963	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
964	     * name is normalized for case- and whitespace-insensitive comparison (see
965	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
966	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
967	     * regardless of creation order, making them members of one household.
968	     *
969	     * @param lastName the owner's last name
970	     * @param postcode the owner's postcode, may be {@code null}
971	     * @return the deterministic household identifier
972	     */
973	    private String householdId(String lastName, String postcode) {
974	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
975	        try {
976	            byte[] digest = MessageDigest.getInstance("SHA-256")
977	                .digest(key.getBytes(StandardCharsets.UTF_8));
978	            StringBuilder hex = new StringBuilder();
979	            for (int i = 0; i < 6; i++) {
980	                hex.append(String.format("%02x", digest[i]));
981	            }
982	            return hex.toString();
983	        } catch (NoSuchAlgorithmException ex) {
984	            throw new IllegalStateException("SHA-256 not available", ex);
985	        }
986	    }
987	
988	    /**
989	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
990	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
991	     * result is lower-cased. A {@code null} value normalizes to the empty string.
992	     *
993	     * @param value the value to normalize, may be {@code null}
994	     * @return the normalized value
995	     */
996	    private String normalizeForComparison(String value) {
997	        if (value == null) {
998	            return "";
999	        }
1000	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1001	    }
1002	
1003	    /**
1004	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
1005	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
1006	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
1007	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
1008	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
1009	     * that is stored, returned, and used for every address comparison (household duplicate detection
1010	     * and the shared household id).
1011	     *
1012	     * @param address the raw address value from the submitted owner payload, may be {@code null}
1013	     * @return the normalized address
1014	     */
1015	    /**
1016	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
1017	     * the structured fields over the flat {@code address} input for backward compatibility. When a
1018	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
1019	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
1020	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
1021	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
1022	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
1023	     *
1024	     * @param owner the owner being created, whose raw address fields are normalized in place
1025	     */
1026	    private void applyAddress(Owner owner) {
1027	        String line1 = owner.getAddressLine1();
1028	        if (line1 != null && !line1.isBlank()) {
1029	            String normalizedLine1 = normalizeAddress(line1);
1030	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
1031	            owner.setAddressLine1(normalizedLine1);
1032	            if (!normalizedLine2.isEmpty()) {
1033	                owner.setAddressLine2(normalizedLine2);
1034	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
1035	            } else {
1036	                owner.setAddressLine2(null);
1037	                owner.setAddress(normalizedLine1);
1038	            }
1039	        } else {
1040	            owner.setAddressLine1(null);
1041	            owner.setAddressLine2(null);
1042	            owner.setAddress(normalizeAddress(owner.getAddress()));
1043	        }
1044	    }
1045	
1046	    private String normalizeAddress(String address) {
1047	        if (address == null) {
1048	            return "";
1049	        }
1050	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
1051	        if (collapsed.isEmpty()) {
1052	            return "";
1053	        }
1054	        String[] tokens = collapsed.split(" ");
1055	        StringBuilder normalized = new StringBuilder();
1056	        for (int i = 0; i < tokens.length; i++) {
1057	            if (i > 0) {
1058	                normalized.append(' ');
1059	            }
1060	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1061	        }
1062	        return normalized.toString();
1063	    }
1064	}
